//! What code generated by `src/codegen/bindgen.ts` hands to a binding's Rust body.
//!
//! Three rules, all enforced by the borrow checker:
//!
//! 1. Running JavaScript, or anything that can call back into Rust, takes `&mut JsCall`.
//! 2. A pointer into memory JavaScript can free, detach, resize or alias is only reachable inside a
//!    closure that borrows a field of `JsCall`, so rule 1 cannot happen while it is live.
//! 3. A JS value is a [`JsValue<'a>`], tied to the host call. It cannot be stored anywhere that
//!    outlives the call; a [`Strong`] and a class's `internalFields` can hold one longer, and the GC visits
//!    those.
//!
//! `test/internal/bindgen-compile-fail` holds one rejected program per hazard.

use core::cell::UnsafeCell;
use core::ffi::c_void;
use core::marker::{PhantomData, PhantomPinned};
use core::ptr::NonNull;

use crate::{
    ArrayBuffer, JSFunction, JSGlobalObject, JSObject, JSString, JSValue, JsError, JsThread,
    MarkedArgumentBuffer, Strong,
};

#[path = "bindgen/extern_types.rs"]
pub mod extern_types;

/// Makes `'a` invariant, so two calls' lifetimes never unify.
type InvariantLifetime<'a> = PhantomData<fn(&'a ()) -> &'a ()>;
type NotSend = PhantomData<*mut ()>;
/// As `bun_opaque::opaque_ffi!`: zero-sized, `!Freeze`, `!Unpin`, so a reference to it is a bare
/// pointer to LLVM (no `noalias`).
type OpaqueFfi = (UnsafeCell<[u8; 0]>, PhantomPinned);

// ───────────────────────────── capabilities ─────────────────────────────

/// The JS heap is alive and this is its thread: allocate, read JS-owned memory, describe an error
/// to throw. Cannot run JavaScript.
#[repr(C)]
pub struct JsHeap<'a>(OpaqueFfi, InvariantLifetime<'a>, NotSend);

/// Reach the Rust payloads of wrapper objects.
#[repr(C)]
pub struct JsPayloads<'a>(OpaqueFfi, InvariantLifetime<'a>, NotSend);

/// A call into Rust on the JS thread. `&mut JsCall` is what runs JavaScript. It is the
/// `JSGlobalObject*` the host function received: both fields are zero-sized at offset 0, and public
/// so a borrow of one leaves the other usable.
#[repr(C)]
pub struct JsCall<'a> {
    pub heap: JsHeap<'a>,
    pub payloads: JsPayloads<'a>,
}

impl<'a> JsHeap<'a> {
    #[inline(always)]
    fn global(&self) -> &JSGlobalObject {
        // SAFETY: a `JsHeap` only exists at the address of a live global (see `JsCall::with`).
        unsafe { JSGlobalObject::opaque_ref_nn(core::ptr::from_ref(self).cast()) }
    }

    /// For generated code.
    #[doc(hidden)]
    #[inline(always)]
    pub fn global_ptr(&self) -> *mut JSGlobalObject {
        self.global().as_mut_ptr()
    }

    #[inline]
    pub fn create_utf8_string(&self, utf8: &[u8]) -> Result<'a, JsValue<'a, JSString>> {
        JsValue::from_js_result(crate::bun_string_jsc::create_utf8_for_js(
            self.global(),
            utf8,
        ))
    }

    #[cold]
    pub fn throw(&self, args: core::fmt::Arguments<'_>) -> Error<'a> {
        Error::to_throw(self.global().create_error_instance(args))
    }

    #[cold]
    pub fn throw_type_error(&self, args: core::fmt::Arguments<'_>) -> Error<'a> {
        Error::to_throw(self.global().create_type_error_instance(args))
    }

    #[cold]
    pub fn throw_range_error(&self, args: core::fmt::Arguments<'_>) -> Error<'a> {
        Error::to_throw(self.global().create_range_error_instance(args))
    }

    #[cold]
    pub fn throw_out_of_memory(&self) -> Error<'a> {
        Error::pending(JsError::OutOfMemory)
    }

    #[cold]
    pub fn throw_value<T>(&self, value: JsValue<'a, T>) -> Error<'a> {
        Error::to_throw(value.0)
    }
}

impl<'a> JsCall<'a> {
    /// For generated thunks, event-loop dispatch, and code that only has a `&JSGlobalObject`.
    ///
    /// # Safety
    /// `global` is the current thread's live global object, and no borrow of an outer `JsCall` is
    /// in use. That holds wherever the engine or the event loop calls into Rust: getting there took
    /// the outer `&mut JsCall`.
    #[inline(always)]
    pub unsafe fn with<R>(
        global: *mut JSGlobalObject,
        f: impl for<'call> FnOnce(&mut JsCall<'call>) -> R,
    ) -> R {
        // SAFETY: `JsCall` is zero-sized and `global` is non-null.
        f(unsafe { &mut *global.cast::<JsCall<'_>>() })
    }

    /// Anything can be done with a `&JSGlobalObject`, so it costs the whole `JsCall` for as long as
    /// the reference lives.
    #[inline(always)]
    pub fn global(&mut self) -> &JSGlobalObject {
        self.heap.global()
    }

    #[inline]
    pub fn js_thread(&mut self) -> JsThread<'_> {
        self.heap.global().js_thread_of_caller_no_frame()
    }

    /// Runs `f`, which takes a `&JSGlobalObject`.
    #[inline]
    pub fn with_global<R>(
        &mut self,
        f: impl FnOnce(&JSGlobalObject) -> crate::JsResult<R>,
    ) -> Result<'a, R> {
        f(self.heap.global()).map_err(Error::pending)
    }

    /// [`with_global`](Self::with_global) for an `f` that returns a JS value.
    #[inline]
    pub fn with_global_value(
        &mut self,
        f: impl FnOnce(&JSGlobalObject) -> crate::JsResult<JSValue>,
    ) -> Result<'a, JsValue<'a>> {
        JsValue::from_js_result(f(self.heap.global()))
    }

    /// Takes the pending exception off the VM.
    pub fn take_exception(&mut self, error: Error<'a>) -> Option<JsValue<'a>> {
        let Error(state, ..) = error;
        match state {
            ErrorState::ToThrow(value) => Some(JsValue::wrap(value)),
            ErrorState::Pending(JsError::Thrown) => {
                self.heap.global().try_take_exception().map(JsValue::wrap)
            }
            ErrorState::Pending(_) => None,
        }
    }
}

// ───────────────────────────── errors ─────────────────────────────

#[derive(Debug)]
enum ErrorState {
    /// Already pending on the VM (or, for the other `JsError`s, what the thunk must do).
    Pending(JsError),
    /// Made under `&JsHeap`; the thunk throws it once the body has returned. `VM::throwException`
    /// notifies the debugger, which can run code, so it must not happen while a body holds borrows.
    ToThrow(JSValue),
}

/// The call failed with a JS exception. Made only by this module; tied to the call, so it cannot be
/// kept and replayed.
#[derive(Debug)]
#[must_use = "dropping this leaves an exception pending (or never throws it)"]
pub struct Error<'a>(ErrorState, InvariantLifetime<'a>, NotSend);
pub type Result<'a, T> = core::result::Result<T, Error<'a>>;

impl<'a> Error<'a> {
    #[inline(always)]
    fn to_throw(value: JSValue) -> Self {
        Error(ErrorState::ToThrow(value), PhantomData, PhantomData)
    }

    #[inline(always)]
    fn pending(error: JsError) -> Self {
        Error(ErrorState::Pending(error), PhantomData, PhantomData)
    }

    /// For generated thunks: leaves the exception pending and returns what the host function
    /// returns to JSC.
    #[doc(hidden)]
    #[cold]
    #[inline(never)]
    pub fn into_host_fn_return(self, cx: &mut JsCall<'a>) -> JSValue {
        let global = cx.global();
        match self.0 {
            ErrorState::Pending(error) => crate::host_fn::host_call_error_value(global, error),
            ErrorState::ToThrow(value) => {
                let _ = global.throw_value(value);
                JSValue::ZERO
            }
        }
    }

    #[cold]
    pub fn into_js_error(self, global: &JSGlobalObject) -> JsError {
        match self.0 {
            ErrorState::Pending(error) => error,
            ErrorState::ToThrow(value) => global.throw_value(value),
        }
    }
}

/// An error type a body may return instead of [`Error`]. The thunk converts it.
pub trait IntoError<'a> {
    fn into_error(self, heap: &JsHeap<'a>) -> Error<'a>;
}
impl<'a> IntoError<'a> for Error<'a> {
    #[inline(always)]
    fn into_error(self, _: &JsHeap<'a>) -> Error<'a> {
        self
    }
}
impl<'a> IntoError<'a> for JsError {
    #[inline(always)]
    fn into_error(self, _: &JsHeap<'a>) -> Error<'a> {
        Error::pending(self)
    }
}
impl<'a> IntoError<'a> for bun_sys::Error {
    #[cold]
    fn into_error(self, heap: &JsHeap<'a>) -> Error<'a> {
        Error::to_throw(crate::SysErrorJsc::to_js(&self, heap.global()))
    }
}
impl<'a> IntoError<'a> for core::convert::Infallible {
    fn into_error(self, _: &JsHeap<'a>) -> Error<'a> {
        match self {}
    }
}

// ───────────────────────────── values ─────────────────────────────

/// A [`JSValue`] held by a host call, known to be a `T` ([`JSString`], [`JSObject`], [`JSFunction`],
/// [`ArrayBuffer`]; `JSValue` is "anything"). `Copy`, one register, no rooting: JSC scans the stack.
/// Keep lists of them in a [`MarkedArgumentBuffer`]; the GC does not look inside a `Vec`.
#[repr(transparent)]
pub struct JsValue<'a, T = JSValue>(JSValue, InvariantLifetime<'a>, PhantomData<*const T>);
impl<T> Clone for JsValue<'_, T> {
    #[inline(always)]
    fn clone(&self) -> Self {
        *self
    }
}
impl<T> Copy for JsValue<'_, T> {}

impl<'a, T> JsValue<'a, T> {
    #[inline(always)]
    fn wrap(value: JSValue) -> Self {
        JsValue(value, PhantomData, PhantomData)
    }

    #[inline(always)]
    fn from_js_result(result: crate::JsResult<JSValue>) -> Result<'a, Self> {
        result.map(Self::wrap).map_err(Error::pending)
    }

    /// For generated thunks.
    ///
    /// # Safety
    /// `value` is a live, non-empty `T` belonging to the call `'a`.
    #[doc(hidden)]
    #[inline(always)]
    pub unsafe fn from_extern(value: JSValue) -> Self {
        Self::wrap(value)
    }

    #[inline(always)]
    pub fn to_js(self) -> JSValue {
        self.0
    }

    #[inline(always)]
    pub fn as_value(self) -> JsValue<'a> {
        JsValue::wrap(self.0)
    }

    /// Keeps the value past the call.
    #[inline]
    pub fn to_strong(self, heap: &JsHeap<'a>) -> Strong {
        Strong::create(self.0, heap.global())
    }
}

impl<'a> JsValue<'a> {
    pub const UNDEFINED: Self = JsValue(JSValue::UNDEFINED, PhantomData, PhantomData);
    pub const NULL: Self = JsValue(JSValue::NULL, PhantomData, PhantomData);

    #[inline(always)]
    pub fn new(_: &JsHeap<'a>, value: JSValue) -> Self {
        debug_assert!(!value.is_empty());
        Self::wrap(value)
    }

    #[inline]
    pub fn from_strong(_: &JsHeap<'a>, strong: &Strong) -> Self {
        Self::wrap(strong.get())
    }

    #[inline(always)]
    pub fn is_undefined(self) -> bool {
        self.0.is_undefined()
    }
    #[inline(always)]
    pub fn is_undefined_or_null(self) -> bool {
        self.0.is_undefined_or_null()
    }
    #[inline]
    pub fn as_function(self) -> Option<JsValue<'a, JSFunction>> {
        self.0.is_callable().then(|| JsValue::wrap(self.0))
    }
}

impl<'a> JsValue<'a, JSFunction> {
    /// Runs JavaScript.
    pub fn call<T>(
        self,
        cx: &mut JsCall<'a>,
        this: JsValue<'a, T>,
        args: &[JsValue<'a>],
    ) -> Result<'a, JsValue<'a>> {
        // SAFETY: `JsValue` is `repr(transparent)` over `JSValue`.
        let args = unsafe { &*(core::ptr::from_ref(args) as *const [JSValue]) };
        JsValue::from_js_result(self.0.call(cx.heap.global(), this.0, args))
    }
}

impl<'a> JsValue<'a, ArrayBuffer> {
    /// The bytes of a typed array, `DataView` or `ArrayBuffer`, or `None` if it is detached.
    /// Pointer and length are read on every call: JavaScript may have run since the last one.
    /// Nothing that could detach, resize or re-home the storage can run inside `f`.
    #[inline]
    pub fn with_bytes<R>(self, heap: &JsHeap<'a>, f: impl FnOnce(&[u8]) -> R) -> Option<R> {
        let array_buffer = self.0.as_array_buffer(heap.global())?;
        if array_buffer.shared || array_buffer.ptr.is_null() && array_buffer.byte_len != 0 {
            return None;
        }
        let result = f(array_buffer.byte_slice());
        self.0.ensure_still_alive();
        Some(result)
    }
}

/// An argument in both forms: converted for use now, and the value itself to hand to something that
/// holds it longer (a class's `internalFields`, a [`Strong`], a JS call, the return value).
#[derive(Clone, Copy)]
pub struct WithValue<'a, T> {
    pub converted: T,
    pub value: JsValue<'a>,
}

// ───────────────────────────── classes ─────────────────────────────

/// The Rust struct of a generated class, stored inside its JS wrapper. `'static`, so it cannot hold a
/// [`JsValue`]. The sweeper drops it with no capability in scope, so `Drop` cannot touch the JS heap.
///
/// # Safety
/// Implemented by generated code only: the offsets describe the generated C++ cell.
pub unsafe trait JsPayload: Sized + 'static {
    #[doc(hidden)]
    const PAYLOAD_OFFSET: usize;
    #[doc(hidden)]
    const INTERNAL_FIELDS_OFFSET: usize;
    /// A new cell whose payload is uninitialized. A null `structure` is the class's own.
    ///
    /// # Safety
    /// The caller writes the payload before anything else runs.
    #[doc(hidden)]
    unsafe fn create_cell(global: *mut JSGlobalObject, structure: *mut c_void) -> NonNull<c_void>;
    /// `value`'s cell if it is a wrapper of `Self`, else null.
    #[doc(hidden)]
    fn cell_from_js(value: JSValue) -> *mut c_void;

    /// A new JS object that owns `self`.
    #[inline]
    fn to_js<'a>(self, heap: &JsHeap<'a>) -> JsWrapper<'a, Self> {
        // SAFETY: a null structure is always valid.
        unsafe { JsWrapper::create_with_structure(heap, core::ptr::null_mut(), self) }
    }

    /// `value` as a wrapper of `Self`, if it is one.
    #[inline]
    fn from_js<'a, T>(value: JsValue<'a, T>) -> Option<JsWrapper<'a, Self>> {
        // SAFETY: C++ checked the class.
        NonNull::new(Self::cell_from_js(value.0))
            .map(|cell| unsafe { JsWrapper::from_extern(cell) })
    }
}

/// The JS object that wraps a `T`. A cell pointer; the payload is reached only through
/// [`JsPayloads`].
#[repr(transparent)]
pub struct JsWrapper<'a, T: JsPayload>(
    NonNull<c_void>,
    InvariantLifetime<'a>,
    PhantomData<*const T>,
);
impl<T: JsPayload> Clone for JsWrapper<'_, T> {
    #[inline(always)]
    fn clone(&self) -> Self {
        *self
    }
}
impl<T: JsPayload> Copy for JsWrapper<'_, T> {}

impl<'a, T: JsPayload> JsWrapper<'a, T> {
    /// For generated thunks.
    ///
    /// # Safety
    /// `cell` is a live wrapper of `T` belonging to the call `'a`.
    #[doc(hidden)]
    #[inline(always)]
    pub unsafe fn from_extern(cell: NonNull<c_void>) -> Self {
        JsWrapper(cell, PhantomData, PhantomData)
    }

    /// For generated constructors.
    ///
    /// # Safety
    /// `structure` is null or a Structure of `T`'s cell class.
    #[doc(hidden)]
    #[inline]
    pub unsafe fn create_with_structure(
        heap: &JsHeap<'a>,
        structure: *mut c_void,
        payload: T,
    ) -> Self {
        // SAFETY: nothing runs between the allocation and the write, which cannot panic.
        unsafe {
            let this = Self::from_extern(T::create_cell(heap.global_ptr(), structure));
            this.payload().write(payload);
            this
        }
    }

    /// For the generated thunk of a method that cannot run JavaScript.
    ///
    /// # Safety
    /// Nothing can reach the payload mutably for `'b`, and the caller's frame holds the cell.
    #[doc(hidden)]
    #[inline(always)]
    pub unsafe fn payload_ref<'b>(self) -> &'b T {
        // SAFETY: forwarded.
        unsafe { &*self.payload() }
    }

    /// As [`payload_ref`](Self::payload_ref).
    ///
    /// # Safety
    /// Nothing else can reach the payload for `'b`, and the caller's frame holds the cell.
    #[doc(hidden)]
    #[inline(always)]
    pub unsafe fn payload_mut<'b>(self) -> &'b mut T {
        // SAFETY: forwarded.
        unsafe { &mut *self.payload() }
    }

    #[inline(always)]
    fn payload(self) -> *mut T {
        // SAFETY: generated offset inside the cell.
        unsafe { self.0.as_ptr().byte_add(T::PAYLOAD_OFFSET).cast() }
    }

    #[inline(always)]
    pub fn as_value(self) -> JsValue<'a, JSObject> {
        JsValue::wrap(JSValue::from_cell(self.0.as_ptr()))
    }

    #[inline(always)]
    pub fn with<R>(self, _: &JsPayloads<'a>, f: impl FnOnce(&T) -> R) -> R {
        // SAFETY: every `&mut T` holds `JsPayloads` exclusively.
        let result = f(unsafe { &*self.payload() });
        self.as_value().0.ensure_still_alive();
        result
    }

    #[inline(always)]
    pub fn with_mut<R>(self, _: &mut JsPayloads<'a>, f: impl FnOnce(&mut T) -> R) -> R {
        // SAFETY: the exclusive borrow of `JsPayloads` excludes every other payload reference.
        let result = f(unsafe { &mut *self.payload() });
        self.as_value().0.ensure_still_alive();
        result
    }

    /// Keeps the wrapper, and so the payload, alive past the call.
    #[inline]
    pub fn to_strong(self, heap: &JsHeap<'a>) -> JsWrapperStrong<T> {
        JsWrapperStrong(self.as_value().to_strong(heap), PhantomData)
    }

    /// For the generated `x_field`.
    ///
    /// # Safety
    /// `index` is one of the class's `internalFields`.
    #[doc(hidden)]
    #[inline(always)]
    pub unsafe fn internal_field(self, _: &JsHeap<'a>, index: usize) -> JsValue<'a> {
        // SAFETY: generated offset inside the cell; they are initialized to `undefined`.
        JsValue::wrap(unsafe {
            self.0
                .as_ptr()
                .byte_add(T::INTERNAL_FIELDS_OFFSET)
                .cast::<JSValue>()
                .add(index)
                .read()
        })
    }

    /// For the generated `set_x_field`.
    ///
    /// # Safety
    /// As [`internal_field`](Self::internal_field).
    #[doc(hidden)]
    #[inline(always)]
    pub unsafe fn set_internal_field<V>(
        self,
        heap: &JsHeap<'a>,
        index: usize,
        value: JsValue<'a, V>,
    ) {
        // SAFETY: as above; C++ stores through the `WriteBarrier`.
        unsafe {
            extern_types::Bun__Bindgen__setInternalField(
                heap.global_ptr(),
                self.0.as_ptr(),
                (T::INTERNAL_FIELDS_OFFSET + index * 8) as u32,
                value.0,
            )
        }
    }
}

/// A [`Strong`] on a wrapper; gives it back to code that has a capability again.
pub struct JsWrapperStrong<T: JsPayload>(Strong, PhantomData<*const T>);
impl<T: JsPayload> JsWrapperStrong<T> {
    #[inline]
    pub fn get<'a>(&self, _: &JsHeap<'a>) -> JsWrapper<'a, T> {
        // SAFETY: made from a `JsWrapper<T>`; a cell value is its pointer.
        unsafe {
            JsWrapper::from_extern(NonNull::new_unchecked(self.0.get().encoded() as *mut c_void))
        }
    }
}

// ───────────────────────────── results ─────────────────────────────

/// Rust to JS, one function per schema type. The schema picks the function, not the Rust type: a
/// `Vec<u8>` is a string under `b.utf8` and an array of numbers under `b.array(b.u8)`.
pub mod to_js {
    use super::*;

    macro_rules! number {
        ($($name:ident: $t:ty => $f:expr;)*) => {$(
            #[inline(always)]
            pub fn $name<'a>(_: &JsHeap<'a>, value: $t) -> Result<'a, JsValue<'a>> {
                Ok(JsValue::wrap($f(value)))
            }
        )*};
    }
    number! {
        bool: bool => JSValue::from;
        i8: i8 => |n| JSValue::js_number_from_int32(i32::from(n));
        u8: u8 => |n| JSValue::js_number_from_int32(i32::from(n));
        i16: i16 => |n| JSValue::js_number_from_int32(i32::from(n));
        u16: u16 => |n| JSValue::js_number_from_int32(i32::from(n));
        i32: i32 => JSValue::js_number_from_int32;
        u32: u32 => |n| JSValue::js_number(f64::from(n));
        i64: i64 => JSValue::js_number_from_int64;
        u64: u64 => JSValue::js_number_from_uint64;
        usize: usize => |n| JSValue::js_number_from_uint64(n as u64);
        f64: f64 => JSValue::js_number;
    }

    #[inline(always)]
    pub fn undefined<'a>(_: &JsHeap<'a>, (): ()) -> Result<'a, JsValue<'a>> {
        Ok(JsValue::UNDEFINED)
    }

    #[inline(always)]
    pub fn any<'a, T>(_: &JsHeap<'a>, value: JsValue<'a, T>) -> Result<'a, JsValue<'a>> {
        Ok(value.as_value())
    }

    #[inline]
    pub fn utf8<'a>(heap: &JsHeap<'a>, value: impl AsRef<[u8]>) -> Result<'a, JsValue<'a>> {
        heap.create_utf8_string(value.as_ref())
            .map(JsValue::as_value)
    }

    #[inline]
    pub fn string<'a>(heap: &JsHeap<'a>, value: bun_core::String) -> Result<'a, JsValue<'a>> {
        JsValue::from_js_result(crate::StringJsc::into_js(value, heap.global()))
    }

    #[inline]
    pub fn array<'a, I: IntoIterator>(
        heap: &JsHeap<'a>,
        items: I,
        mut convert: impl FnMut(&JsHeap<'a>, I::Item) -> Result<'a, JsValue<'a>>,
    ) -> Result<'a, JsValue<'a>> {
        MarkedArgumentBuffer::new(|values| {
            for item in items {
                values.append(convert(heap, item)?.0);
            }
            // SAFETY: `values` is live for the call.
            JsValue::from_js_result(crate::call_zero_is_throw(heap.global(), || unsafe {
                extern_types::Bun__Bindgen__constructArray(heap.global_ptr(), values)
            }))
        })
    }

    /// For generated dictionaries: an object with the generated Structure at `structure_index`. An
    /// empty value is a member that is absent.
    #[doc(hidden)]
    #[inline]
    pub fn object_with_structure<'a>(
        heap: &JsHeap<'a>,
        structure_index: u32,
        values: &[JSValue],
    ) -> Result<'a, JsValue<'a>> {
        // SAFETY: `values` is on the caller's stack, where the GC sees it; this cannot throw.
        Ok(JsValue::wrap(unsafe {
            extern_types::Bun__Bindgen__createObject(
                heap.global_ptr(),
                structure_index,
                values.as_ptr(),
                values.len(),
            )
        }))
    }

    /// For generated enums.
    #[doc(hidden)]
    #[inline]
    pub fn enumeration_value<'a>(heap: &JsHeap<'a>, index: u32) -> Result<'a, JsValue<'a>> {
        // SAFETY: a generated index; this cannot throw.
        Ok(JsValue::wrap(unsafe {
            extern_types::Bun__Bindgen__enumerationValueToJS(heap.global_ptr(), index)
        }))
    }
}

/// For generated thunks: a body's result as what the host function returns to JSC.
#[doc(hidden)]
#[inline(always)]
pub fn host_fn_return<'a, T, E: IntoError<'a>>(
    cx: &mut JsCall<'a>,
    result: core::result::Result<T, E>,
    convert: impl FnOnce(&JsHeap<'a>, T) -> Result<'a, JsValue<'a>>,
) -> JSValue {
    let error = match result {
        Ok(value) => match convert(&cx.heap, value) {
            Ok(value) => return value.0,
            Err(error) => error,
        },
        Err(error) => error.into_error(&cx.heap),
    };
    error.into_host_fn_return(cx)
}
